package com.shipflow.order;
import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.assertj.core.api.Assertions.assertThat;
class ShipmentOrderMapperXmlTest { @Test void writesAllOrderAggregateRowsAndKeepsTenantPredicates(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/order/ShipmentOrderMapper.xml")); assertThat(xml).contains("shipment_order","shipment_quote_snapshot","shipment_address","shipment_package","shipment_item","audit_log","tenant_id=#{tenantId}","transitionStatus","advanceDraftVersion","current_status='DRAFT' AND version=#{version}","version,created_at","DELETE si").doesNotContain("SELECT *");}catch(Exception e){throw new AssertionError(e);}} @Test void idempotencyXmlHasTenantScope(){try{String xml=Files.readString(Path.of("src/main/resources/mapper/order/ShipmentOrderIdempotencyMapper.xml"));assertThat(xml).contains("scope_tenant_id=#{tenantId}","resource_type='SHIPMENT_ORDER'");}catch(Exception e){throw new AssertionError(e);}} }
